def _limit_by_sql(self, **kwargs: Any) -> str:
    (n, offset, by) = self._limit_by
    by = ",".join(term.get_sql(with_alias=True, **kwargs) for term in by)
    if offset != 0:
        return f" LIMIT {n} OFFSET {offset} BY ({by})"
    else:
        return f" LIMIT {n} BY ({by})"
